def longest(strings: List[str]) -> Optional[str]:
    if not strings:
        return None
    filtered = [s for s in strings if len(s) <= 2]
    if not filtered:
        return None
    max_len = max(len(s) for s in filtered)
    for s in strings:
        if len(s) <= 2 and len(s) == max_len:
