from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int, bool]:
    sum_value = 0
    prod_value = 1
    for n in numbers:
        sum_value += n
        prod_value *= n
    # Check for close elements with a fixed threshold
    sorted_numbers = sorted(numbers)
    threshold = 0.5
    for i in range(len(sorted_numbers) - 1):
        if sorted_numbers[i+1] - sorted_numbers[i] < threshold:
            return (sum_value, prod_value, True)
    return (sum_value, prod_value, False)

