def factorize(n: int) -> list:
    import math
    if n % 2 == 0:
        # Count even digits in the number
        count = 0
        for digit in str(n):
            if int(digit) % 2 == 0:
                count += 1
        return [count]
    else:
        # Original prime factorization logic
        fact = []
        i = 2
        while i <= int(math.sqrt(n) + 1):
            if n % i == 0:
