from typing import List

def all_prime_prefixes(string: str) -> List[str]:
    """ Return list of all prefixes from shortest to longest of the input string whose lengths are prime numbers """
    result: List[str] = []
    for i in range(len(string)):
        prefix = string[:i+1]
        length = len(prefix)
        flg = 0
        if length == 1:
            flg = 1
        for j in range(2, length):
            if length % j == 0:
                flg = 1
        if flg == 0 or length == 2:
            result.append(prefix)
    return result

