def triples_sum_to_zero(l: list):
    l.sort()
    result = []
    n = len(l)
    for i in range(n - 2):
        if i > 0 and l[i] == l[i - 1]:
            continue
        left = i + 1
        right = n - 1
        while left < right:
            current_sum = l[i] + l[left] + l[right]
            if current_sum == 0:
                result.append((l[i], l[left], l[right]))
                while left < right and l[left] == l[left + 1]:
                    left += 1
                while left < right and l[right] == l[right - 1]:
                    right -= 1
                left += 1
                right -= 1
            elif current_sum < 0:
                left += 1
            else:
                right -= 1
    result.sort()
    return result

