def sort_even(l: list):
    if not l:
        return -1
    evens = l[::2]
    odds = l[1::2]
    evens.sort()
    ans = []
    for e, o in zip(evens, odds):
        ans.extend([e, o])
    if len(evens) > len(odds):
        ans.append(evens[-1])
    avg = round(sum(evens) / len(evens))
    return bin(avg)

